describe('Dropdown Accessibility Tests', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.get('.dropdown-toggle').click(); // Open the dropdown
    });

    it('should close the dropdown when Escape key is pressed', () => {
        cy.get('.dropdown-menu').should('be.visible'); // Ensure dropdown is visible
        cy.get('body').type('{esc}'); // Simulate Escape key press
        cy.get('.dropdown-menu').should('not.exist'); // Verify dropdown is closed
    });

    it('should not close the dropdown when other keys are pressed', () => {
        cy.get('.dropdown-menu').should('be.visible'); // Ensure dropdown is visible
        cy.get('body').type('a'); // Simulate pressing a non-Escape key
        cy.get('.dropdown-menu').should('be.visible'); // Verify dropdown is still open
    });
});
